const getJson=async url=>{const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(`${url}: ${r.status}`);return r.json();};
const download=(name,data)=>{const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),0);};


const state={waterStations:[],waterStationNotifications:[],waterStationSummary:null,stationRoutingAudit:null,waterRouting:{schemaVersion:1,zones:{}},stationMap:null,selectedRoutingZoneId:null,tab:'dashboard',rules:[],zones:[],zoneRegistry:{counts:{registered:0,active:0,legacy:0}},conditions:{zones:{}},health:null,runtime:null,oceanDiagnostics:null,cacheAudit:null,implementationAudit:null,editingId:null};
