function setLocalJsonSafely(key,payload){try{localStorage.setItem(key,JSON.stringify(payload));return true}catch(error){console.warn(`[RavRadar] Lokal browsercache kunne ikke gemmes for ${key}; Supabase-gemning fortsætter.`,error);return false}}
function adminRules(){try{return JSON.parse(localStorage.getItem(RULES_KEY)||'[]')}catch{return[]}}
function saveAdminRules(rules){localStorage.setItem(RULES_KEY,JSON.stringify(rules));state.rules=rules;queueAdminDocumentSave('rules',{schemaVersion:1,rules,updatedAt:new Date().toISOString()});}
function history(){try{return JSON.parse(localStorage.getItem(HISTORY_KEY)||'[]')}catch{return[]}}
function addHistory(action,rule){const rows=history();rows.unshift({at:new Date().toISOString(),action,rule:structuredClone(rule)});localStorage.setItem(HISTORY_KEY,JSON.stringify(rows.slice(0,200)));}
function uid(){return `admin-${Date.now()}-${Math.random().toString(36).slice(2,7)}`}

async function boot(){
 const [zoneRegistry,conditions,health,runtime,stationInventory,stationRouting,stationRoutingAudit,oceanDiagnostics,cacheAudit,implementationAudit,...files]=await Promise.all([
  loadZoneRegistry({forceRefresh:true}).catch(()=>({all:[],active:[],legacy:[],counts:{registered:0,active:0,legacy:0}})),getJson('./data/live/conditions.json').catch(()=>({zones:{}})),getJson('./data/live/weather-health.json').catch(()=>null),getJson('./data/live/ravradar-runtime-diagnostics.json').catch(()=>null),getJson('./data/live/dmi-water-stations.json').catch(()=>({stations:[]})),getJson('./data/water-level-station-routing.json').catch(()=>({schemaVersion:1,zones:{}})),getJson('./data/live/water-station-routing-audit.json').catch(()=>null),getJson('./data/diagnostics/dmi-ocean-diagnostics.json').catch(()=>null),getJson('./data/diagnostics/dmi-cache-audit.json').catch(()=>null),getJson('./data/diagnostics/implementation-plan-audit.json').catch(()=>null),
  getJson('./rules/national-rules.json').catch(()=>({rules:[]})),getJson('./rules/local-rules.json').catch(()=>({rules:[]})),getJson('./rules/experimental-rules.json').catch(()=>({rules:[]}))]);
 state.zoneRegistry=zoneRegistry;state.zones=zoneRegistry.active||[];state.conditions=conditions;state.health=health;state.runtime=runtime;state.stationRoutingAudit=stationRoutingAudit;state.oceanDiagnostics=oceanDiagnostics;state.cacheAudit=cacheAudit;state.implementationAudit=implementationAudit;state.waterStations=stationInventory.stations||[];state.waterStationNotifications=stationInventory.notifications||[];state.waterStationSummary=stationInventory.summary||null;state.waterRouting=await loadAdminDocument('water-level-station-routing',stationRouting);setLocalJsonSafely(WATER_ROUTING_KEY,state.waterRouting);const remoteRules=await loadAdminDocument('rules',{rules:adminRules()});if(Array.isArray(remoteRules?.rules)){localStorage.setItem(RULES_KEY,JSON.stringify(remoteRules.rules));}const remoteReviews=await loadAdminDocument('direction-reviews',{zones:directionReviews()});if(remoteReviews?.zones)localStorage.setItem(DIRECTION_REVIEW_KEY,JSON.stringify(remoteReviews.zones));
 const shipped=files.flatMap(f=>f.rules||[]).map(r=>({...r,_origin:'projekt'}));
 state.rules=[...shipped,...adminRules().map(r=>({...r,_origin:'admin'}))];
 render();
}

