function saveWaterRouting(){state.waterRouting.updatedAt=new Date().toISOString();setLocalJsonSafely(WATER_ROUTING_KEY,state.waterRouting);queueAdminDocumentSave('water-level-station-routing',state.waterRouting);}
function zoneCenter(feature){const p=feature?.properties?.dataPoint||feature?.properties?.seaPoint;if(Array.isArray(p)&&p.length===2)return p;const ring=feature?.geometry?.coordinates?.[0]||[];if(!ring.length)return[10,56];return[ring.reduce((a,x)=>a+x[0],0)/ring.length,ring.reduce((a,x)=>a+x[1],0)/ring.length];}
function haversineAdmin(a,b){const r=x=>x*Math.PI/180,dLat=r(b[1]-a[1]),dLon=r(b[0]-a[0]),q=Math.sin(dLat/2)**2+Math.cos(r(a[1]))*Math.cos(r(b[1]))*Math.sin(dLon/2)**2;return 6371*2*Math.atan2(Math.sqrt(q),Math.sqrt(1-q));}
function stationRegistryState(station){
 const status=String(station?.registryStatus??station?.properties?.status??'').toLowerCase();
 if(['retired','historical','inactive','deleted'].includes(status))return 'retired';
 if(['active','operational'].includes(status))return 'active';
 return 'unknown';
}
function stationLifecycleKnown(station){return station&&('deliveryStatus' in station||'hasEverDelivered' in station||'forecastCacheStatus' in station||'overallUsabilityStatus' in station);}
function normalizedSelectedStations(route){
 const rows=Array.isArray(route?.stations)?route.stations:[];
 rows.forEach((entry,index)=>{entry.role=index===0?'primary':'secondary';});
 return rows;
}
function inverseDistancePreview(zoneId,entries){
 const zone=state.zones.find(z=>z.properties?.id===zoneId),center=zoneCenter(zone);
 const rows=(entries||[]).map(entry=>{const station=state.waterStations.find(x=>String(x.stationId)===String(entry.stationId));const distanceKm=station?haversineAdmin(center,station.point):null;return {entry,station,distanceKm};});
 if(rows.length===1)return rows.map(row=>({...row,weight:1}));
 if(rows.length<2||rows.some(row=>!Number.isFinite(row.distanceKm)))return rows.map(row=>({...row,weight:null}));
 const inverse=rows.map(row=>1/Math.max(.25,row.distanceKm)),total=inverse.reduce((sum,value)=>sum+value,0)||1;
 return rows.map((row,index)=>({...row,weight:inverse[index]/total}));
}

function stationObservationLabel(station){
 const status=station?.deliveryStatus;
 if(status==='delivering')return 'Leverer nu';
 if(status==='temporarily-missing')return 'Midlertidigt uden ny måling';
 if(status==='not-delivering')return 'Leverer ikke nu';
 if(station?.hasEverDelivered===true)return 'Har leveret tidligere';
 if(station?.hasEverDelivered===false)return 'Har aldrig leveret';
 return 'Observationsstatus ikke dokumenteret';
}
function stationCacheLabel(station){
 if(station?.forecastCacheStatus==='valid'&&Number.isFinite(Date.parse(station?.forecastCacheValidUntil??'')))return `Cache gyldig til ${new Date(station.forecastCacheValidUntil).toLocaleString('da-DK')}`;
 if(station?.forecastCacheStatus==='expired')return 'Prognosecache udløbet';
 if(station?.forecastCacheStatus==='none')return 'Ingen prognosecache';
 return 'Cachestatus ikke dokumenteret';
}
function stationUsabilityLabel(station){
 if(station?.overallUsabilityStatus==='forecast-cache-only')return 'Kan anvendes via cache';
 if(station?.overallUsabilityStatus==='live-or-recent-observation')return 'Kan anvendes';
 if(station?.overallUsabilityStatus==='unavailable')return 'Utilgængelig';
 if(stationRegistryState(station)==='retired')return 'Udfaset i DMI-registeret';
 return 'Anvendelighed ikke dokumenteret';
}
function stationStatusHtml(station){
 return `<div class="station-status-grid"><span class="station-status-pill">Observation: ${esc(stationObservationLabel(station))}</span><span class="station-status-pill">${esc(stationCacheLabel(station))}</span><span class="station-status-pill">Samlet: ${esc(stationUsabilityLabel(station))}</span></div>`;
}
function automaticStationRecommendation(zoneId){
 const zone=state.zones.find(z=>z.properties?.id===zoneId),center=zoneCenter(zone);
 // Aktuel vandstandskildestatus er autoritativ. Et gammelt auditdokument må ikke
 // fastholde et tomt automatisk valg efter at kilderne er blevet brugbare.
 return recommendWaterStationBracket({zoneId,zoneName:zone?.properties?.name,point:center,coastLine:zone?.properties?.coastLine,onshoreDirectionDeg:zone?.properties?.onshoreDirectionDeg,stations:state.waterStations,haversineKm:haversineAdmin});
}
function stationDeliveryLabel(station){
 const status=station?.deliveryStatus;
 if(status==='delivering')return 'Leverer nu';
 if(status==='temporarily-missing')return 'Midlertidigt uden måling';
 if(status==='not-delivering')return 'Leverer ikke';
 if(station?.hasEverDelivered===true)return 'Har leveret tidligere';
 if(station?.hasEverDelivered===false)return 'Har aldrig leveret';
 return 'Leveringsstatus ikke dokumenteret';
}
function stationDeliveryClass(station){
 const status=station?.deliveryStatus;
 return status==='delivering'?'active':status==='temporarily-missing'?'warning':status==='not-delivering'?'danger':'muted';
}
function renderStationNotifications(){
 const rows=(state.waterStationNotifications||[]).slice(0,8);
 if(!rows.length)return '<p class="muted">Ingen stationshændelser registreret endnu.</p>';
 return `<div class="station-notification-list">${rows.map(item=>`<div class="station-notification ${esc(item.type)}"><b>${esc(item.stationName||item.stationId)}</b><span>${esc(item.message||item.type)}</span><small>${item.generatedAt?new Date(item.generatedAt).toLocaleString('da-DK'):''}</small></div>`).join('')}</div>`;
}
function renderWaterStations(){
 const zoneId=state.selectedRoutingZoneId||state.zones[0]?.properties?.id;state.selectedRoutingZoneId=zoneId;const route=state.waterRouting.zones?.[zoneId]||{enabled:false,method:'inverse-distance',requireAll:true,stations:[]};const automatic=automaticStationRecommendation(zoneId);
 content.innerHTML=`<article class="admin-card"><div class="rule-card-head"><div><h2>Stationsstatus og hændelser</h2><p class="muted">RavRadar bevarer kendte stationer. Statusfelter vises kun som fakta, når de er dokumenteret; manglende status må ikke fremstilles som driftsstop.</p></div></div>${renderStationNotifications()}</article><article class="admin-card"><div class="rule-card-head"><div><h2>Vandstandsstationer på kort</h2><p class="muted">RavRadars automatiske valg vises altid. Aktivér kun administratorvalg, hvis en zone skal afvige. Ændringer gemmes automatisk.</p></div><div class="toolbar"><button id="saveWaterRoutingNow" class="admin-button">Gem nu</button><button id="exportWaterRouting" class="admin-button secondary">Eksportér backup</button><button id="resetWaterRouting" class="admin-button secondary">Nulstil lokalt</button></div></div></article><div class="station-routing-layout"><article class="admin-card station-routing-panel"><label>Zone<select id="routingZone">${state.zones.map(z=>`<option value="${esc(z.properties?.id)}" ${z.properties?.id===zoneId?'selected':''}>${esc(z.properties?.name||z.properties?.id)}</option>`).join('')}</select></label><section class="automatic-station-box"><div class="rule-card-head"><div><h3>RavRadars automatiske valg</h3><p class="hint">${esc(automatic.method)}</p>${automatic.completeBracket===false?`<p class="status-warning"><b>Advarsel:</b> ${esc(automatic.reason||'Stationerne indrammer ikke zonen korrekt.')}</p>`:''}</div><span class="badge active">Standard</span></div><div id="automaticRoutingSelection"></div><details id="automaticCalculation"><summary>Vis automatisk beregning</summary><div id="automaticCandidates"></div></details><button id="useAutomaticAsOverride" class="admin-button secondary" ${automatic.stations.length?'':'disabled'}>Kopiér valget til administratorvalg</button></section><hr><label class="switch-line"><input id="routingEnabled" type="checkbox" ${route.enabled?'checked':''}> Brug administratorvalgte stationer for denne zone</label><div class="override-status ${route.enabled?'enabled':'disabled'}">${route.enabled?'Administratorens valg erstatter automatikken':'Automatikken er aktiv'}</div><label>Metode<select id="routingMethod"><option value="inverse-distance" ${route.method!=='manual-weights'?'selected':''}>Automatiske afstandsvægte</option><option value="manual-weights" ${route.method==='manual-weights'?'selected':''}>Manuelle vægte</option></select></label><label class="switch-line"><input id="routingRequireAll" type="checkbox" ${route.requireAll!==false?'checked':''}> Kræv alle valgte stationer</label><div id="routingSelection"></div><p class="hint">Klik station på kortet for at tilføje. Maksimum to stationer. Manuelle valg anvendes kun, når kontakten ovenfor er aktiv.</p></article><article class="admin-card"><div id="stationRoutingMap" class="station-routing-map"></div><div class="direction-legend"><span><i class="dot sea"></i> Zone</span><span><i class="dot station"></i> Øvrig DMI-station</span><span><i class="dot automatic-station"></i> Automatisk valgt</span><span><i class="dot selected-station"></i> Administratorvalgt</span><span><i class="dot automatic-admin-station"></i> Begge valg</span><span><i class="dot retired-station"></i> Udfaset station</span></div></article></div>`;
 const saveControls=()=>{const r=state.waterRouting.zones[zoneId]||(state.waterRouting.zones[zoneId]={stations:[]});r.enabled=document.querySelector('#routingEnabled').checked;r.method=document.querySelector('#routingMethod').value;r.requireAll=document.querySelector('#routingRequireAll').checked;r.reviewed=true;saveWaterRouting();drawSelection();drawMap();};
 document.querySelector('#routingZone').onchange=e=>{state.selectedRoutingZoneId=e.target.value;renderWaterStations();};['routingEnabled','routingMethod','routingRequireAll'].forEach(id=>document.querySelector('#'+id).onchange=saveControls);
 document.querySelector('#saveWaterRoutingNow').onclick=async()=>{await saveAdminDocumentNow('water-level-station-routing',state.waterRouting)};document.querySelector('#exportWaterRouting').onclick=()=>download('water-level-station-routing.json',state.waterRouting);document.querySelector('#resetWaterRouting').onclick=()=>{if(confirm('Fjern lokale stationvalg og genindlæs projektfilen?')){localStorage.removeItem(WATER_ROUTING_KEY);location.reload();}};
 document.querySelector('#useAutomaticAsOverride').onclick=()=>{const r=state.waterRouting.zones[zoneId]||(state.waterRouting.zones[zoneId]={stations:[]});r.stations=automatic.stations.map(st=>({stationId:String(st.stationId),role:st.role,weight:Number(st.weight.toFixed(3))}));r.enabled=true;r.method='inverse-distance';r.requireAll=true;r.reviewed=true;saveWaterRouting();renderWaterStations();};
 function drawAutomatic(){document.querySelector('#automaticRoutingSelection').innerHTML=automatic.stations.map((st,i)=>`<div class="station-choice automatic"><b>${i===0?'Primær':'Sekundær'}: ${esc(st.name||st.stationId)}</b><small>${Number(st.distanceKm).toFixed(1)} km · ${esc(st.role||'side')} · ${(Number(st.weight)*100).toFixed(1)} %</small></div>`).join('')||'<div class="empty">Ingen gyldige DMI-stationer blev indlæst.</div>';document.querySelector('#automaticCandidates').innerHTML=`<ol class="station-candidate-list">${automatic.candidates.map((st,i)=>`<li><b>${esc(st.name||st.stationId)}</b><span>${Number(st.distanceKm).toFixed(1)} km · langs kyst ${Number(st.alongCoastKm??st.alongKm??0).toFixed(1)} km${automatic.stations.some(x=>String(x.stationId)===String(st.stationId))?' · valgt':''}</span></li>`).join('')}</ol><p class="hint">Rangeringen bruger zonens lokale kystlinje. Systemet kræver normalt én station på hver sin side langs kysten; luftlinjeafstand alene er ikke nok.</p>`;}
 function drawSelection(){const r=state.waterRouting.zones?.[zoneId]||{stations:[]};normalizedSelectedStations(r);const preview=inverseDistancePreview(zoneId,r.stations);document.querySelector('.override-status').className=`override-status ${r.enabled?'enabled':'disabled'}`;document.querySelector('.override-status').textContent=r.enabled?'Administratorens valg erstatter automatikken':'Automatikken er aktiv';document.querySelector('#routingSelection').innerHTML=preview.map((row,i)=>{const entry=row.entry,st=row.station,dist=row.distanceKm;const weightText=r.method==='manual-weights'?'manuel vægt':Number.isFinite(row.weight)?`afstandsvægt ${(row.weight*100).toFixed(1)} %`:'afstandsvægt kan ikke beregnes';return `<div class="station-choice admin"><b>${i===0?'Primær':'Sekundær'}: ${esc(st?.name||entry.stationId)}</b><small>${dist==null?'Ukendt afstand':dist.toFixed(1)+' km'} · ${esc(stationDeliveryLabel(st))} · ${weightText}</small>${r.method==='manual-weights'?`<input type="number" min="0" step="0.05" value="${entry.weight??(i===0?0.5:0.5)}" data-weight="${i}">`:''}<button class="admin-button danger" data-remove-station="${i}">Fjern</button></div>`}).join('')||'<div class="empty">Ingen administratorstationer valgt.</div>';document.querySelectorAll('[data-remove-station]').forEach(b=>b.onclick=()=>{r.stations.splice(Number(b.dataset.removeStation),1);normalizedSelectedStations(r);if(!r.stations.length)r.enabled=false;saveWaterRouting();drawSelection();drawMap();});document.querySelectorAll('[data-weight]').forEach(inp=>inp.onchange=()=>{r.stations[Number(inp.dataset.weight)].weight=Number(inp.value);saveWaterRouting();});}
 function drawMap(){if(state.stationMap){state.stationMap.remove();state.stationMap=null;}const zone=state.zones.find(z=>z.properties?.id===zoneId),center=zoneCenter(zone),r=state.waterRouting.zones?.[zoneId]||{stations:[]};const autoIds=new Set(automatic.stations.map(x=>String(x.stationId))),adminIds=new Set((r.stations||[]).map(x=>String(x.stationId)));const map=L.map('stationRoutingMap').setView([center[1],center[0]],8);state.stationMap=map;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap'}).addTo(map);L.geoJSON(zone,{style:{color:'#3aa7ff',weight:4,fillOpacity:.08}}).addTo(map);L.circleMarker([center[1],center[0]],{radius:8,color:'#3aa7ff',fillOpacity:1}).bindTooltip(zone.properties?.name||zoneId).addTo(map);for(const st of state.waterStations){const sid=String(st.stationId),auto=autoIds.has(sid),admin=adminIds.has(sid),both=auto&&admin;const retired=stationRegistryState(st)==='retired',unavailable=st.overallUsabilityStatus==='unavailable';const color=both?'#a978ff':admin?'#ff6b6b':auto?'#38d996':retired?'#777':'#d8a232';const marker=L.circleMarker([st.point[1],st.point[0]],{radius:(auto||admin)?8:5,color,weight:(auto||admin)?4:2,fillOpacity:retired?.45:.9,dashArray:retired?'4 3':null}).bindTooltip(`${st.name} · ${haversineAdmin(center,st.point).toFixed(1)} km · ${stationUsabilityLabel(st)} · ${stationObservationLabel(st)} · ${stationCacheLabel(st)}${auto?' · automatisk valgt':''}${admin?' · administratorvalgt':''}`);marker.on('click',()=>{if((retired||unavailable)&&!admin&&!confirm(`${st.name} er markeret som ${retired?'udfaset i DMI-registeret':'utilgængelig'}. Vil du fortsætte med et manuelt valg?`))return;const list=r.stations||(r.stations=[]),idx=list.findIndex(x=>String(x.stationId)===sid);if(idx>=0)list.splice(idx,1);else if(list.length<2)list.push({stationId:sid,role:list.length?'secondary':'primary',weight:0.5});else alert('Der kan højst vælges to stationer. Fjern en først.');normalizedSelectedStations(r);r.enabled=list.length>0;r.reviewed=true;saveWaterRouting();renderWaterStations();});marker.addTo(map);}}
 drawAutomatic();drawSelection();drawMap();
}

function renderZones(){content.innerHTML=`<article class="admin-card"><h2>Zoner</h2><div class="toolbar"><input id="zoneSearch" placeholder="Søg zone"><select id="zoneType"><option value="">Alle kysttyper</option>${[...new Set(state.zones.map(z=>z.properties?.coastType).filter(Boolean))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select></div></article><div id="zoneList" class="admin-table-wrap"></div>`;const draw=()=>{const q=document.querySelector('#zoneSearch').value.toLowerCase(),t=document.querySelector('#zoneType').value;const rows=state.zones.filter(z=>(!t||z.properties?.coastType===t)&&JSON.stringify(z.properties).toLowerCase().includes(q));document.querySelector('#zoneList').innerHTML=`<table class="admin-table"><thead><tr><th>Zone</th><th>Kysttype</th><th>Område</th><th>Vejrkilde</th></tr></thead><tbody>${rows.slice(0,250).map(z=>{const p=z.properties||{},w=state.conditions.zones?.[p.id]||{};return `<tr><td>${esc(p.name||p.id)}</td><td>${esc(p.coastType||'–')}</td><td>${esc(p.region||p.area||'–')}</td><td>${esc(w.provider||'ingen data')}</td></tr>`}).join('')}</tbody></table>`};document.querySelector('#zoneSearch').oninput=draw;document.querySelector('#zoneType').onchange=draw;draw();}



function directionReviews(){try{return JSON.parse(localStorage.getItem(DIRECTION_REVIEW_KEY)||'{}')}catch{return{}}}
function saveDirectionReviews(rows){localStorage.setItem(DIRECTION_REVIEW_KEY,JSON.stringify(rows));queueAdminDocumentSave('direction-reviews',{schemaVersion:1,zones:rows,updatedAt:new Date().toISOString()});}
function normalizeDeg(v){return ((Number(v)%360)+360)%360;}
function angleDiff(a,b){const d=Math.abs(normalizeDeg(a)-normalizeDeg(b));return Math.min(d,360-d);}
function bearingDeg(from,to){const [lon1,lat1]=from.map(x=>Number(x)*Math.PI/180),[lon2,lat2]=to.map(x=>Number(x)*Math.PI/180);const y=Math.sin(lon2-lon1)*Math.cos(lat2);const x=Math.cos(lat1)*Math.sin(lat2)-Math.sin(lat1)*Math.cos(lat2)*Math.cos(lon2-lon1);return normalizeDeg(Math.atan2(y,x)*180/Math.PI);}
function destinationPoint(origin,bearing,distanceKm=4){const R=6371,[lon1,lat1]=origin.map(x=>Number(x)*Math.PI/180),br=normalizeDeg(bearing)*Math.PI/180,d=distanceKm/R;const lat2=Math.asin(Math.sin(lat1)*Math.cos(d)+Math.cos(lat1)*Math.sin(d)*Math.cos(br));const lon2=lon1+Math.atan2(Math.sin(br)*Math.sin(d)*Math.cos(lat1),Math.cos(d)-Math.sin(lat1)*Math.sin(lat2));return [lon2*180/Math.PI,lat2*180/Math.PI];}
function directionLabel(deg){const labels=['N','NØ','Ø','SØ','S','SV','V','NV'];return `${labels[Math.round(normalizeDeg(deg)/45)%8]} ${Math.round(normalizeDeg(deg))}°`;}
function pointDistanceKm(a,b){if(!a||!b)return null;const R=6371,[lon1,lat1]=a.map(x=>Number(x)*Math.PI/180),[lon2,lat2]=b.map(x=>Number(x)*Math.PI/180);const dLat=lat2-lat1,dLon=lon2-lon1,h=Math.sin(dLat/2)**2+Math.cos(lat1)*Math.cos(lat2)*Math.sin(dLon/2)**2;return 2*R*Math.asin(Math.sqrt(h));}
function directionAuditPriority(feature,reviews){const p=feature.properties||{},r=reviews[p.id];if(r?.status==='verified')return 99;if(!p.dataPoint||!p.pinPoint)return 0;const distance=pointDistanceKm(p.dataPoint,p.pinPoint),pointBearing=bearingDeg(p.dataPoint,p.pinPoint),diff=angleDiff(p.onshoreDirectionDeg,pointBearing);if(distance<.15||distance>8||diff>45)return 1;if((p.onshoreDirectionReviewStatus||'').includes('manual')||(p.placementReview&&p.placementReview!=='verified')||p.directionAnchorAuditRecommended===true)return 2;return 3;}

let directionMap=null,directionLayers=[];
function clearDirectionLayers(){if(directionMap)directionLayers.forEach(x=>directionMap.removeLayer(x));directionLayers=[];}
function addDirectionLayer(layer){layer.addTo(directionMap);directionLayers.push(layer);return layer;}
function baseAnchors(properties,review){
 const stored=Array.isArray(review?.anchors)&&review.anchors.length?review.anchors:Array.isArray(properties.directionAnchors)&&properties.directionAnchors.length?properties.directionAnchors:[{id:'primary',name:'Primær kystdel',dataPoint:properties.dataPoint,pinPoint:properties.pinPoint,onshoreDirectionDeg:properties.onshoreDirectionDeg,weight:1}];
 return stored.map((a,i)=>({id:String(a.id||`anchor-${i+1}`),name:String(a.name||`Kystdel ${i+1}`),dataPoint:Array.isArray(a.dataPoint)?a.dataPoint.map(Number):null,pinPoint:Array.isArray(a.pinPoint)?a.pinPoint.map(Number):null,onshoreDirectionDeg:normalizeDeg(a.onshoreDirectionDeg??(a.dataPoint&&a.pinPoint?bearingDeg(a.dataPoint,a.pinPoint):0)),weight:Number.isFinite(Number(a.weight))?Math.max(.1,Number(a.weight)):1,verified:Boolean(a.verified)}));
}
function arrowEnd(anchor){return anchor.dataPoint?destinationPoint(anchor.dataPoint,anchor.onshoreDirectionDeg,4):null;}
function drawDirectionZone(feature,anchors,selectedAnchorId,onPointMoved){
 if(!window.L)return;const p=feature.properties||{};clearDirectionLayers();
 const coords=[];const collect=x=>{if(Array.isArray(x)&&typeof x[0]==='number'&&typeof x[1]==='number')coords.push([x[1],x[0]]);else if(Array.isArray(x))x.forEach(collect)};collect(feature.geometry?.coordinates||[]);
 if(coords.length)addDirectionLayer(L.polygon(coords,{color:'#d8a232',weight:4,fillOpacity:.06,interactive:false}));
 if(Array.isArray(p.coastLine)&&p.coastLine.length)addDirectionLayer(L.polyline(p.coastLine.map(x=>[x[1],x[0]]),{color:'#5ee093',weight:5,interactive:false}));
 anchors.forEach((anchor,index)=>{
  const selected=anchor.id===selectedAnchorId;const suffix=anchors.length>1?` · ${anchor.name}`:'';
  if(anchor.dataPoint){const marker=addDirectionLayer(L.marker([anchor.dataPoint[1],anchor.dataPoint[0]],{draggable:true,title:`Marint datapunkt${suffix}`,icon:L.divIcon({className:'direction-point-icon',html:`<span class="direction-point sea ${selected?'selected':''}">${index+1}</span>`,iconSize:[28,28],iconAnchor:[14,14]})}).bindTooltip(`Blåt punkt: marint datapunkt${suffix}`));marker.on('dragend',e=>{const ll=e.target.getLatLng();onPointMoved(anchor.id,'dataPoint',[ll.lng,ll.lat]);});}
  if(anchor.pinPoint){const marker=addDirectionLayer(L.marker([anchor.pinPoint[1],anchor.pinPoint[0]],{draggable:true,title:`Strand-/landpunkt${suffix}`,icon:L.divIcon({className:'direction-point-icon',html:`<span class="direction-point land ${selected?'selected':''}">${index+1}</span>`,iconSize:[28,28],iconAnchor:[14,14]})}).bindTooltip(`Grønt punkt: strand-/landpunkt${suffix}`));marker.on('dragend',e=>{const ll=e.target.getLatLng();onPointMoved(anchor.id,'pinPoint',[ll.lng,ll.lat]);});}
  const end=arrowEnd(anchor);if(anchor.dataPoint&&end){addDirectionLayer(L.polyline([[anchor.dataPoint[1],anchor.dataPoint[0]],[end[1],end[0]]],{color:selected?'#ff4f4f':'#ff8d8d',weight:selected?7:4,opacity:selected?1:.7,interactive:false}));addDirectionLayer(L.circleMarker([end[1],end[0]],{radius:selected?6:4,color:'#ff4f4f',fillColor:'#ff4f4f',fillOpacity:1,interactive:false}).bindTooltip(`Retningen peger hertil: ${directionLabel(anchor.onshoreDirectionDeg)}${suffix}`));}
 });
 const bounds=directionLayers.flatMap(x=>x.getBounds?[x.getBounds()]:[]).reduce((a,b)=>a?a.extend(b):b,null);if(bounds?.isValid()&&!directionMap.__hasFit){directionMap.fitBounds(bounds.pad(.3));directionMap.__hasFit=true;}
}

function renderDirectionAudit(){
 const reviews=directionReviews();const active=state.zones.filter(z=>z.properties?.zoneStatus==='active');const verified=active.filter(z=>reviews[z.properties?.id]?.status==='verified').length;
 content.innerHTML=`<article class="admin-card direction-intro"><div class="rule-card-head"><div><h2>Geografisk kontrol af kystdele</h2><p>Flyt punkterne direkte på kortet. <b>Blå skal ligge i havet</b>, <b>grøn ved stranden/land</b>, og den røde retning skal pege fra havet ind mod land.</p></div><span class="badge">${verified}/${active.length} zoner godkendt</span></div><ol class="direction-steps"><li>Vælg en zone og derefter den kystdel, du vil redigere.</li><li>Træk det blå og grønne punkt til de rigtige steder.</li><li>Klik <b>Beregn retning fra punkterne</b>, eller finjustér graderne.</li><li>Ved en bugtet kyst kan du tilføje flere kystdele. Hver kystdel får sit eget havpunkt, landpunkt og retning.</li><li>Godkend zonen og download til sidst en ny <code>zones.geojson</code>.</li></ol><p class="hint">Den røde cirkel er slutningen af retningen – altså den ende, retningen peger imod. Ændringer gemmes lokalt i browseren, indtil du eksporterer zonefilen.</p></article>
 <div class="direction-layout"><article class="admin-card direction-queue"><div class="toolbar"><input id="directionSearch" placeholder="Søg efter zone"><select id="directionFilter"><option value="pending">Ikke godkendte først</option><option value="uncertain">Kun mistænkelige</option><option value="verified">Kun godkendte</option><option value="all">Alle zoner</option></select></div><div id="directionZoneList" class="direction-zone-list"></div></article>
 <article class="admin-card direction-work"><div id="directionEmpty" class="empty">Vælg en zone i listen.</div><div id="directionEditor" hidden><div class="rule-card-head"><div><span id="directionStatus" class="badge"></span><h2 id="directionName"></h2><p id="directionMeta" class="muted"></p></div><button id="directionOpenMain" class="admin-button secondary">Vis på hovedkortet</button></div>
 <div id="directionMap" class="direction-map"></div><div class="direction-legend"><span><i class="dot sea"></i> Flytbart havpunkt</span><span><i class="dot land"></i> Flytbart landpunkt</span><span><i class="line coast"></i> Kystlinje</span><span><i class="line arrow"></i> Retningen peger mod den røde cirkel</span></div>
 <section class="anchor-manager"><div class="rule-card-head"><div><h3>Kystdele i zonen</h3><p class="hint">En lige kyst behøver normalt én. Brug flere ved bugter, odder eller kyster der vender forskelligt.</p></div><button id="anchorAdd" type="button" class="admin-button secondary">+ Tilføj kystdel</button></div><div id="anchorTabs" class="anchor-tabs"></div></section>
 <div class="form-grid anchor-editor"><label>Navn på kystdelen<input id="anchorName" placeholder="Fx vestlige kyst"></label><label>Vægt<input id="anchorWeight" type="number" min="0.1" max="5" step="0.1"><span class="hint">Normalt 1. Højere tal bruges kun, hvis denne kystdel fysisk repræsenterer en større del af zonen.</span></label><label>Havpunkt – længdegrad<input id="anchorSeaLon" type="number" step="0.000001"></label><label>Havpunkt – breddegrad<input id="anchorSeaLat" type="number" step="0.000001"></label><label>Landpunkt – længdegrad<input id="anchorLandLon" type="number" step="0.000001"></label><label>Landpunkt – breddegrad<input id="anchorLandLat" type="number" step="0.000001"></label></div>
 <div class="direction-controls"><label>Pålandsretning <strong id="directionValue"></strong><input id="directionRange" type="range" min="0" max="359" step="1"></label><label>Præcis grad<input id="directionNumber" type="number" min="0" max="359" step="1"></label></div><div class="toolbar direction-nudge"><button id="directionMinus5" class="admin-button secondary" type="button">−5°</button><button id="directionPlus5" class="admin-button secondary" type="button">+5°</button><button id="directionUsePointBearing" class="admin-button secondary" type="button">Beregn retning fra punkterne</button><button id="anchorDelete" class="admin-button danger" type="button">Slet denne kystdel</button></div><div id="directionChecks" class="direction-checks"></div>
 <fieldset class="direction-confirmations"><legend>Bekræft zonen</legend><label><input id="directionConfirmSea" type="checkbox"> Alle blå punkter ligger i havet</label><label><input id="directionConfirmLand" type="checkbox"> Alle grønne punkter ligger ved deres kyst/land</label><label><input id="directionConfirmArrow" type="checkbox"> Alle røde retninger peger fra hav mod land</label></fieldset><label>Bemærkning<textarea id="directionNote" placeholder="Fx: To kystdele fordi bugten vender både mod vest og syd."></textarea></label><div class="direction-actions"><button id="directionFlag" class="admin-button secondary">Kræver senere kontrol</button><button id="directionApprove" class="admin-button" disabled>Godkend og gå til næste</button></div></div></article></div>
 <article class="admin-card"><h2>Eksport</h2><p>Download den komplette zonefil. Primær kystdel gemmes også i de gamle felter for bagudkompatibilitet; alle kystdele gemmes i <code>directionAnchors</code>.</p><div class="toolbar"><button id="directionExport" class="admin-button">Download zones.geojson</button><button id="directionExportReview" class="admin-button secondary">Download kontrolrapport</button><button id="directionReset" class="admin-button danger">Nulstil lokale godkendelser</button></div></article>`;
 let selectedId=null,selectedAnchorId=null,currentAnchors=[];const list=document.querySelector('#directionZoneList');
 const visibleZones=()=>{const q=document.querySelector('#directionSearch').value.trim().toLowerCase(),f=document.querySelector('#directionFilter').value;return active.filter(z=>{const p=z.properties||{},r=reviews[p.id],priority=directionAuditPriority(z,reviews);if(q&&!`${p.id} ${p.name} ${p.region}`.toLowerCase().includes(q))return false;if(f==='verified')return r?.status==='verified';if(f==='uncertain')return priority<=2&&r?.status!=='verified';if(f==='pending')return r?.status!=='verified';return true;}).sort((a,b)=>directionAuditPriority(a,reviews)-directionAuditPriority(b,reviews)||(a.properties?.name||'').localeCompare(b.properties?.name||'','da'));};
 const drawList=()=>{const rows=visibleZones();list.innerHTML=rows.length?rows.map(z=>{const p=z.properties||{},r=reviews[p.id];return `<button class="direction-zone-row ${selectedId===p.id?'selected':''}" data-zone-id="${esc(p.id)}"><span><b>${esc(p.name||p.id)}</b><small>${esc(p.id)} · ${esc(p.region||'')}</small></span><span class="badge ${r?.status==='verified'?'active':r?.status==='flagged'?'draft':''}">${r?.status==='verified'?'Godkendt':r?.status==='flagged'?'Senere kontrol':'Ikke kontrolleret'}</span></button>`}).join(''):'<div class="empty">Ingen zoner matcher.</div>';list.querySelectorAll('[data-zone-id]').forEach(b=>b.onclick=()=>selectZone(b.dataset.zoneId));};
 const persistDraft=()=>{if(!selectedId)return;reviews[selectedId]={...(reviews[selectedId]||{}),anchors:structuredClone(currentAnchors),note:document.querySelector('#directionNote')?.value.trim()||'',updatedAt:new Date().toISOString()};saveDirectionReviews(reviews);};
 const selectedAnchor=()=>currentAnchors.find(a=>a.id===selectedAnchorId)||currentAnchors[0];
 const updateChecks=()=>{const a=selectedAnchor();if(!a)return;const bearing=a.dataPoint&&a.pinPoint?bearingDeg(a.dataPoint,a.pinPoint):null;document.querySelector('#directionChecks').innerHTML=`<div class="metric-card"><span>Hav → land fra punkter</span><strong>${bearing==null?'Mangler':directionLabel(bearing)}</strong></div><div class="metric-card"><span>Valgt retning</span><strong>${directionLabel(a.onshoreDirectionDeg)}</strong></div><div class="metric-card"><span>Forskel</span><strong>${bearing==null?'–':Math.round(angleDiff(a.onshoreDirectionDeg,bearing))+'°'}</strong></div><div class="metric-card"><span>Afstand</span><strong>${a.dataPoint&&a.pinPoint?pointDistanceKm(a.dataPoint,a.pinPoint).toFixed(2)+' km':'–'}</strong></div>`;};
 const redrawMap=()=>{const feature=active.find(z=>z.properties?.id===selectedId);if(feature&&directionMap)drawDirectionZone(feature,currentAnchors,selectedAnchorId,(anchorId,key,coords)=>{const a=currentAnchors.find(x=>x.id===anchorId);a[key]=coords;if(key==='dataPoint'||key==='pinPoint'){if(a.dataPoint&&a.pinPoint)a.onshoreDirectionDeg=Math.round(bearingDeg(a.dataPoint,a.pinPoint));}persistDraft();renderAnchorEditor();redrawMap();});};
 const renderAnchorTabs=()=>{const wrap=document.querySelector('#anchorTabs');wrap.innerHTML=currentAnchors.map((a,i)=>`<button type="button" data-anchor-id="${esc(a.id)}" class="anchor-tab ${a.id===selectedAnchorId?'active':''}"><b>${i+1}. ${esc(a.name)}</b><small>${directionLabel(a.onshoreDirectionDeg)}</small></button>`).join('');wrap.querySelectorAll('[data-anchor-id]').forEach(b=>b.onclick=()=>{selectedAnchorId=b.dataset.anchorId;renderAnchorEditor();redrawMap();});};
 const renderAnchorEditor=()=>{const a=selectedAnchor();if(!a)return;renderAnchorTabs();document.querySelector('#anchorName').value=a.name;document.querySelector('#anchorWeight').value=a.weight;document.querySelector('#anchorSeaLon').value=a.dataPoint?.[0]??'';document.querySelector('#anchorSeaLat').value=a.dataPoint?.[1]??'';document.querySelector('#anchorLandLon').value=a.pinPoint?.[0]??'';document.querySelector('#anchorLandLat').value=a.pinPoint?.[1]??'';document.querySelector('#directionRange').value=a.onshoreDirectionDeg;document.querySelector('#directionNumber').value=Math.round(a.onshoreDirectionDeg);document.querySelector('#directionValue').textContent=directionLabel(a.onshoreDirectionDeg);document.querySelector('#anchorDelete').disabled=currentAnchors.length<=1;updateChecks();};
 const selectZone=id=>{selectedId=id;drawList();const feature=active.find(z=>z.properties?.id===id),p=feature.properties||{},r=reviews[id]||{};currentAnchors=baseAnchors(p,r);selectedAnchorId=currentAnchors[0]?.id;document.querySelector('#directionEmpty').hidden=true;document.querySelector('#directionEditor').hidden=false;document.querySelector('#directionName').textContent=p.name||id;document.querySelector('#directionMeta').textContent=`${id} · ${p.region||'Ukendt område'} · ${p.coastType||'ukendt kysttype'}`;document.querySelector('#directionStatus').textContent=r.status==='verified'?'Godkendt':r.status==='flagged'?'Kræver senere kontrol':'Ikke kontrolleret';document.querySelector('#directionNote').value=r.note||'';const c=r.confirmations||{};document.querySelector('#directionConfirmSea').checked=Boolean(c.seaPointInWater);document.querySelector('#directionConfirmLand').checked=Boolean(c.landPointAtCoast);document.querySelector('#directionConfirmArrow').checked=Boolean(c.arrowSeaToLand);setTimeout(()=>{if(!directionMap){directionMap=L.map('directionMap',{zoomControl:true});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(directionMap);}directionMap.__hasFit=false;directionMap.invalidateSize();renderAnchorEditor();redrawMap();},0);document.querySelector('#directionOpenMain').onclick=()=>window.open(`./?zone=${encodeURIComponent(id)}`,'_blank');updateApprove();};
 const modifyAnchor=(fn)=>{const a=selectedAnchor();if(!a)return;fn(a);persistDraft();renderAnchorEditor();redrawMap();};
 ['anchorName','anchorWeight','anchorSeaLon','anchorSeaLat','anchorLandLon','anchorLandLat'].forEach(id=>document.querySelector('#'+id).onchange=()=>modifyAnchor(a=>{a.name=document.querySelector('#anchorName').value.trim()||a.name;a.weight=Math.max(.1,Number(document.querySelector('#anchorWeight').value)||1);a.dataPoint=[Number(document.querySelector('#anchorSeaLon').value),Number(document.querySelector('#anchorSeaLat').value)];a.pinPoint=[Number(document.querySelector('#anchorLandLon').value),Number(document.querySelector('#anchorLandLat').value)];}));
 const changeDirection=v=>modifyAnchor(a=>a.onshoreDirectionDeg=normalizeDeg(v));document.querySelector('#directionRange').oninput=e=>changeDirection(e.target.value);document.querySelector('#directionNumber').onchange=e=>changeDirection(e.target.value);document.querySelector('#directionMinus5').onclick=()=>changeDirection(selectedAnchor().onshoreDirectionDeg-5);document.querySelector('#directionPlus5').onclick=()=>changeDirection(selectedAnchor().onshoreDirectionDeg+5);document.querySelector('#directionUsePointBearing').onclick=()=>modifyAnchor(a=>{if(a.dataPoint&&a.pinPoint)a.onshoreDirectionDeg=Math.round(bearingDeg(a.dataPoint,a.pinPoint));});
 document.querySelector('#anchorAdd').onclick=()=>{const source=selectedAnchor()||currentAnchors[0];const id=`anchor-${Date.now().toString(36)}`;currentAnchors.push({id,name:`Kystdel ${currentAnchors.length+1}`,dataPoint:source?.dataPoint?[source.dataPoint[0]+.01,source.dataPoint[1]]:null,pinPoint:source?.pinPoint?[source.pinPoint[0]+.01,source.pinPoint[1]]:null,onshoreDirectionDeg:source?.onshoreDirectionDeg??0,weight:1,verified:false});selectedAnchorId=id;persistDraft();renderAnchorEditor();redrawMap();};
 document.querySelector('#anchorDelete').onclick=()=>{if(currentAnchors.length<=1)return;if(!confirm('Slet denne kystdel?'))return;currentAnchors=currentAnchors.filter(a=>a.id!==selectedAnchorId);selectedAnchorId=currentAnchors[0].id;persistDraft();renderAnchorEditor();redrawMap();};
 const confirmationState=()=>({seaPointInWater:document.querySelector('#directionConfirmSea').checked,landPointAtCoast:document.querySelector('#directionConfirmLand').checked,arrowSeaToLand:document.querySelector('#directionConfirmArrow').checked});function updateApprove(){const c=confirmationState();document.querySelector('#directionApprove').disabled=!(c.seaPointInWater&&c.landPointAtCoast&&c.arrowSeaToLand&&currentAnchors.length);};['directionConfirmSea','directionConfirmLand','directionConfirmArrow'].forEach(id=>document.querySelector('#'+id).onchange=updateApprove);
 document.querySelector('#directionApprove').onclick=()=>{const c=confirmationState();if(!(c.seaPointInWater&&c.landPointAtCoast&&c.arrowSeaToLand))return;reviews[selectedId]={status:'verified',anchors:structuredClone(currentAnchors.map(a=>({...a,verified:true}))),note:document.querySelector('#directionNote').value.trim(),verifiedAt:new Date().toISOString(),confirmations:c};saveDirectionReviews(reviews);drawList();const next=visibleZones().find(z=>z.properties?.id!==selectedId);if(next)selectZone(next.properties.id);};document.querySelector('#directionFlag').onclick=()=>{reviews[selectedId]={status:'flagged',anchors:structuredClone(currentAnchors),note:document.querySelector('#directionNote').value.trim(),updatedAt:new Date().toISOString(),confirmations:confirmationState()};saveDirectionReviews(reviews);drawList();};
 document.querySelector('#directionSearch').oninput=drawList;document.querySelector('#directionFilter').onchange=drawList;document.querySelector('#directionExport').onclick=()=>{const output=structuredClone(state.zoneRegistry.collection||{type:'FeatureCollection',features:state.zoneRegistry.all||state.zones});for(const f of output.features||[]){const p=f.properties||{},r=reviews[p.id];if(r?.anchors?.length){p.directionAnchors=r.anchors.map(a=>({...a,onshoreDirectionDeg:Math.round(normalizeDeg(a.onshoreDirectionDeg))}));const primary=p.directionAnchors[0];p.dataPoint=primary.dataPoint;p.pinPoint=primary.pinPoint;p.onshoreDirectionDeg=primary.onshoreDirectionDeg;p.onshoreDirectionSource='manual multi-anchor geographic review in RavRadar admin';p.onshoreDirectionAuditedAt=r.verifiedAt||r.updatedAt;p.onshoreDirectionReviewStatus=r.status==='verified'?'manually-verified':'manual-review-needed';if(r.note)p.onshoreDirectionReviewNote=r.note;}}download('zones.geojson',output);};document.querySelector('#directionExportReview').onclick=()=>download(`ravradar-geografisk-kontrol-${new Date().toISOString().slice(0,10)}.json`,{schemaVersion:'2.0',exportedAt:new Date().toISOString(),reviews});document.querySelector('#directionReset').onclick=()=>{if(confirm('Nulstil alle lokale geografiske kontroller?')){localStorage.removeItem(DIRECTION_REVIEW_KEY);renderDirectionAudit();}};
 drawList();const first=visibleZones()[0];if(first)selectZone(first.properties.id);
}

function renderObservations(){const obs=JSON.parse(localStorage.getItem('ravradar-observations-v2')||'[]');const finds=obs.filter(x=>x.found||x.result==='found').length;content.innerHTML=`<div class="admin-grid"><article class="admin-card"><h2>Observationer</h2><div class="metric">${obs.length}</div></article><article class="admin-card"><h2>Registrerede fund</h2><div class="metric">${finds}</div></article><article class="admin-card"><h2>Vejrsnapshots</h2><div class="metric">${obs.filter(x=>x.weatherSnapshot).length}</div><p class="muted">Bevares ved central oprydning</p></article></div><article class="admin-card"><h2>Eksport og databeskyttelse</h2><p>Eksporten fjerner bruger-id og præcis GPS-position. Vejrsnapshot og regelforklaring bevares til analyse.</p><button id="exportObs" class="admin-button">Eksportér pseudonymiseret JSON</button></article>`;document.querySelector('#exportObs').onclick=()=>{const rows=obs.map(({anonymous_id,user_id,gps,...r})=>({...r,gps:gps?{accuracy:gps.accuracy??null}:null}));download('ravradar-observationer.json',{exportedAt:new Date().toISOString(),privacyProfile:'pseudonymised',rows})};}

function renderDocumentation(){content.innerHTML=`<article class="admin-card"><span class="eyebrow">Projektviden</span><h2>RavRadar dokumentationscenter</h2><p>Åbn håndbogen, gældende RDKS, aktive krav, implementeringsstatus, kendte problemer og masterlog ét sted.</p><div class="toolbar"><a class="admin-button" href="documentation.html" target="_blank" rel="noopener">Åbn dokumentationscenter</a><a class="admin-button secondary" href="handbook.html" target="_blank" rel="noopener">Åbn håndbogen direkte</a></div></article><div class="admin-grid"><article class="admin-card"><h2>Gældende sandhed</h2><p>Den første fil, der læses i en ny chat.</p></article><article class="admin-card"><h2>Implementeringsstatus</h2><p>Viser hvad der er færdigt, delvist og mangler.</p></article><article class="admin-card"><h2>Aktive krav</h2><p>Kun aktuelle krav må styre nye kodeændringer.</p></article></div>`;}

function renderSystem(){const session=currentSession();content.innerHTML=`<div class="admin-grid"><article class="admin-card"><h2>Version</h2><div class="metric">${VERSION}</div></article><article class="admin-card"><h2>Supabase</h2><div class="metric status-good">Forbundet</div><p class="muted">${esc(session?.user?.email||'Owner')} · owner</p></article><article class="admin-card"><h2>Central ekspertlagring</h2><div class="metric ${centralAdminStorageEnabled()?'status-good':'status-warning'}">${centralAdminStorageEnabled()?'Aktiv':'Lokal fallback'}</div></article><article class="admin-card"><h2>Lokale administratorregler</h2><div class="metric">${adminRules().length}</div></article><article class="admin-card"><h2>Regelhistorik</h2><div class="metric">${history().length}</div></article></div><article class="admin-card"><h2>Vedligeholdelse</h2><div class="toolbar"><button id="exportDiag" class="admin-button secondary">Eksportér diagnostik</button><button id="clearCaches" class="admin-button danger">Ryd RavRadar-caches</button><button id="logoutAdmin" class="admin-button secondary">Lås administration</button></div><p class="hint">Cacheknappen rydder kun caches, hvis navn starter med “ravradar”. Den sletter ikke observationer, ture eller regler.</p></article><article class="admin-card"><h2>Seneste regelændringer</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Tid</th><th>Handling</th><th>Regel</th></tr></thead><tbody>${history().slice(0,20).map(x=>`<tr><td>${new Date(x.at).toLocaleString('da-DK')}</td><td>${esc(x.action)}</td><td>${esc(x.rule?.name)}</td></tr>`).join('')||'<tr><td colspan="3">Ingen ændringer</td></tr>'}</tbody></table></div></article>`;document.querySelector('#exportDiag').onclick=()=>{const waterLevelZones=Object.fromEntries(Object.entries(state.conditions.zones||{}).map(([zoneId,z])=>[zoneId,{zoneName:z.waterLevel?.diagnostic?.zoneName||state.zones.find(f=>f.properties?.id===zoneId)?.properties?.name||zoneId,provider:z.provider,currentWaterLevelCm:z.current?.waterLevelCm??null,waterLevel:z.waterLevel??null,modelSteps:z.modelSteps??null,dmiCache:z.dmiCache??null,attempts:z.attempts??[],acquisition:z.acquisition??null}]));download('ravradar-diagnostik.json',{version:VERSION,exportedAt:new Date().toISOString(),conditionsGeneratedAt:state.conditions.generatedAt??null,health:state.health,weatherEngine:state.conditions.weatherEngine??null,dataQuality:state.conditions.dataQuality??null,weatherZoneCount:Object.keys(state.conditions.zones||{}).length,zoneCount:state.zoneRegistry.counts.registered,activeZoneCount:state.zoneRegistry.counts.active,legacyZoneCount:state.zoneRegistry.counts.legacy,adminRuleCount:adminRules().length,waterLevelDiagnostics:{description:'Aktuel vandstand er baseret på DMI oceanObs: direkte lokal station eller kystbaseret interpolation mellem én station på hver side. Prognosemodeller vises separat.',zones:waterLevelZones}})};document.querySelector('#clearCaches').onclick=async()=>{if(!confirm('Ryd RavRadars app-caches?'))return;for(const name of await caches.keys())if(name.toLowerCase().startsWith('ravradar'))await caches.delete(name);alert('RavRadar-caches er ryddet.');};document.querySelector('#logoutAdmin').onclick=async()=>{const {signOut}=await import('../services/auth-service.js?v=4.0.207');await signOut();location.replace('./admin.html')};}


function renderHistory(){
 const zones=state.zones.map(z=>z.properties).sort((a,b)=>(a.name||'').localeCompare(b.name||'','da'));
 content.innerHTML=`<article class="admin-card"><h2>Historisk analyse</h2><p class="muted">Filtrér registrerede ravture og sammenlign fund med det vejrsnapshot og den RavScore, der blev gemt på turdagen.</p><div class="toolbar"><input id="historyDate" type="date"><select id="historyZone"><option value="">Alle zoner</option>${zones.map(z=>`<option value="${esc(z.id)}">${esc(z.name)}</option>`).join('')}</select><select id="historyResult"><option value="">Alle resultater</option><option value="none">Intet fund</option><option value="small">Små stykker</option><option value="medium">Noget rav</option><option value="good">Godt fund</option></select><button id="clearHistory" class="admin-button secondary">Ryd filtre</button></div></article><div id="historyOutput"></div>`;
 const draw=()=>{const summary=historicalSummary({date:document.querySelector('#historyDate').value||null,zoneId:document.querySelector('#historyZone').value||null,result:document.querySelector('#historyResult').value||null});document.querySelector('#historyOutput').innerHTML=`<div class="admin-grid"><article class="admin-card"><h3>Ture</h3><div class="metric">${summary.count}</div></article><article class="admin-card"><h3>Fund</h3><div class="metric">${summary.finds}</div></article><article class="admin-card"><h3>Fundrate</h3><div class="metric">${summary.successRate==null?'–':Math.round(summary.successRate*100)+'%'}</div></article><article class="admin-card"><h3>Gns. RavScore</h3><div class="metric">${summary.averages.ravScore??'–'}</div></article></div><article class="admin-card admin-table-wrap"><table class="admin-table"><thead><tr><th>Dato</th><th>Zone</th><th>Resultat</th><th>RavScore</th><th>Vandstand</th><th>Vind</th><th>Bølger</th><th>Kilde</th></tr></thead><tbody>${summary.rows.map(r=>`<tr><td>${esc(String(r.observed_at).slice(0,10))}</td><td>${esc(r.zone_name||r.zone_id)}</td><td>${esc(r.result)}</td><td>${esc(r.rav_score??'–')}</td><td>${esc(r.water_level_cm??'–')} cm</td><td>${esc(r.wind_speed_mps??'–')} m/s</td><td>${esc(r.wave_height_m??'–')} m</td><td>${esc(r.weather_snapshot?.provider||r.weather_snapshot?.current?.provider||'–')}</td></tr>`).join('')||'<tr><td colspan="8">Ingen observationer matcher filtrene.</td></tr>'}</tbody></table></article>`};
 ['historyDate','historyZone','historyResult'].forEach(id=>document.querySelector('#'+id).onchange=draw);document.querySelector('#clearHistory').onclick=()=>{document.querySelector('#historyDate').value='';document.querySelector('#historyZone').value='';document.querySelector('#historyResult').value='';draw()};draw();
}
function renderLearning(){
 const analysis=analyzeObservations(),model=loadAdaptiveModel(),decisions=decisionHistory();
 const versions=listAdaptiveModelVersions();
 content.innerHTML=`<div class="admin-grid"><article class="admin-card"><h2>Aktiv model</h2><div class="metric">v${model.version}</div><p class="muted">${esc(model.source)}${model.updatedAt?' · '+new Date(model.updatedAt).toLocaleString('da-DK'):''}</p></article><article class="admin-card"><h2>Datagrundlag</h2><div class="metric">${analysis.sampleSize||0}</div><p class="muted">${analysis.status==='ready'?'Klar til forslag':'Der kræves mindst 12 ture og fire af hvert udfald.'}</p></article><article class="admin-card"><h2>Beslutninger</h2><div class="metric">${decisions.length}</div><p class="muted">Godkendelser og afvisninger på denne enhed</p></article></div><article class="admin-card"><div class="rule-card-head"><div><h2>Machine Learning Studio</h2><p class="muted">Godkendte forslag opretter en ny aktiv modelversion. Alle versioner gemmes, så du kan rulle tilbage uden at kode.</p></div><button id="rollbackModel" class="admin-button danger">Nulstil model</button></div></article><div id="suggestionList" class="admin-grid">${analysis.suggestions?.length?analysis.suggestions.map(suggestionCard).join(''):`<div class="empty">${analysis.status==='ready'?'Ingen nye statistisk underbyggede forslag.':'Der er endnu ikke tilstrækkeligt balanceret feedback til sikre forslag.'}</div>`}</div><article class="admin-card"><h2>Modelversioner</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Version</th><th>Kilde</th><th>Tid</th><th></th></tr></thead><tbody>${versions.map(v=>`<tr><td>v${v.version}${v.version===model.version?' · aktiv':''}</td><td>${esc(v.source)}</td><td>${v.updatedAt?new Date(v.updatedAt).toLocaleString('da-DK'):'Fabriksmodel'}</td><td>${v.version===model.version?'':`<button class="admin-button secondary" data-restore-model="${v.version}">Aktivér som ny version</button>`}</td></tr>`).join('')}</tbody></table></div></article><article class="admin-card"><h2>Beslutningshistorik</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Tid</th><th>Beslutning</th><th>Forslag</th><th>Model</th></tr></thead><tbody>${decisions.slice(0,50).map(d=>`<tr><td>${new Date(d.at).toLocaleString('da-DK')}</td><td>${d.decision==='approved'?'Godkendt':'Afvist'}</td><td>${esc(d.suggestion?.title||d.suggestionId)}</td><td>${esc(d.modelVersion??'–')}</td></tr>`).join('')||'<tr><td colspan="4">Ingen beslutninger endnu.</td></tr>'}</tbody></table></div></article>`;
 content.querySelectorAll('[data-approve-ml]').forEach(b=>b.onclick=()=>{const s=analysis.suggestions.find(x=>x.id===b.dataset.approveMl);if(!s)return;if(!confirm(`Godkend “${s.title}”? Ændringen bruges i fremtidige prognoser.`))return;const updated=applyApprovedSuggestion(s);recordDecision(s,'approved',updated.version);renderLearning();});
 content.querySelectorAll('[data-reject-ml]').forEach(b=>b.onclick=()=>{const s=analysis.suggestions.find(x=>x.id===b.dataset.rejectMl);if(!s)return;recordDecision(s,'rejected',model.version);renderLearning();});
 document.querySelector('#rollbackModel').onclick=()=>{if(confirm('Nulstil alle godkendte modeltilpasninger?')){rollbackAdaptiveModel();renderLearning();}};content.querySelectorAll('[data-restore-model]').forEach(button=>button.onclick=()=>{if(confirm(`Aktivér model v${button.dataset.restoreModel} som en ny version?`)){activateAdaptiveModelVersion(Number(button.dataset.restoreModel));renderLearning();}});
}
function suggestionCard(s){return `<article class="admin-card ml-suggestion"><div class="rule-card-head"><div><span class="badge">${esc(s.confidence)}% sikkerhed</span><h3>${esc(s.title)}</h3></div></div><p>${esc(s.description)}</p><p><b>Foreslået effekt:</b> ${esc(s.expectedEffect)}</p><p class="hint">Datagrundlag: ${esc(s.evidence.successful)} fund og ${esc(s.evidence.unsuccessful)} ture uden fund. Ingen kildekode omskrives.</p><div class="rule-card-actions"><button class="admin-button" data-approve-ml="${esc(s.id)}">Godkend og aktivér</button><button class="admin-button danger" data-reject-ml="${esc(s.id)}">Afvis</button></div></article>`}

function openRuleEditor(rule=null,advice=false){state.editingId=rule?.id||null;const r=rule||{id:uid(),name:'',status:'draft',kind:advice?'annotation':'bonus',knowledgeClass:'expert',confidence:'mellem',priority:500,geography:{scope:'national'},source:{type:'expert',title:''},conditions:{},effect:{scoreAdjustment:0,explanation:''},version:1};document.querySelector('#ruleDialogTitle').textContent=rule?'Redigér regel':advice?'Nyt godt råd':'Ny regel';document.querySelector('#ruleFormBody').innerHTML=`<div class="form-grid"><label class="full">Titel<input name="name" required value="${esc(r.name)}" placeholder="Fx Frisk pålandsvind efter stille periode"></label><label>Status<select name="status"><option value="draft" ${r.status==='draft'?'selected':''}>Kladde</option><option value="active" ${r.status==='active'?'selected':''}>Aktiv</option><option value="inactive" ${r.status==='inactive'?'selected':''}>Inaktiv</option></select></label><label>Type<select name="kind"><option value="bonus" ${r.kind==='bonus'?'selected':''}>Giver bonus</option><option value="penalty" ${r.kind==='penalty'?'selected':''}>Giver fradrag</option><option value="persistence" ${r.kind==='persistence'?'selected':''}>Virker i timer/dage efter hændelse</option><option value="gate" ${r.kind==='gate'?'selected':''}>Blokerer vurdering</option><option value="override" ${r.kind==='override'?'selected':''}>Sætter fast score</option><option value="annotation" ${r.kind==='annotation'?'selected':''}>Godt råd uden score</option></select></label><label>Videnstype<select name="knowledgeClass"><option value="expert" ${r.knowledgeClass==='expert'?'selected':''}>Erfaring fra ravjæger</option><option value="documented" ${r.knowledgeClass==='documented'?'selected':''}>Dokumenteret viden</option><option value="data-derived" ${r.knowledgeClass==='data-derived'?'selected':''}>Udledt af RavRadar-data</option><option value="hypothesis" ${r.knowledgeClass==='hypothesis'?'selected':''}>Hypotese til afprøvning</option></select></label><label>Tillid<select name="confidence"><option ${r.confidence==='lav'?'selected':''}>lav</option><option ${r.confidence==='mellem'?'selected':''}>mellem</option><option ${r.confidence==='stor'?'selected':''}>stor</option></select></label><label>Kilde / ravjæger<input name="sourceTitle" value="${esc(r.source?.title||'')}" placeholder="Navn, bog, artikel eller samtale"></label><label>Prioritet<input name="priority" type="number" min="0" max="10000" value="${esc(r.priority??500)}"><span class="hint">Lavt tal køres først.</span></label><label>Hvor gælder rådet?<select name="scope" id="geoScope"><option value="national" ${r.geography?.scope==='national'?'selected':''}>Hele Danmark</option><option value="coastType" ${r.geography?.scope==='coastType'?'selected':''}>Bestemte kysttyper</option><option value="zone" ${r.geography?.scope==='zone'?'selected':''}>Bestemte zoner</option></select></label><label class="full" id="geoValuesLabel">Områder<input name="geoValues" value="${esc((r.geography?.zoneIds||r.geography?.coastTypes||[]).join(', '))}" placeholder="Skriv zone-id'er eller kysttyper adskilt med komma"></label><div class="full"><h3>Betingelser</h3><p class="hint">Tilføj kun de forhold, som skal være opfyldt. Alle valgte betingelser skal passe samtidig.</p><div id="conditionList" class="condition-list"></div><button type="button" id="addCondition" class="admin-button secondary">+ Tilføj betingelse</button></div><label>Scoreændring<input name="scoreAdjustment" type="number" min="-100" max="100" value="${esc(r.effect?.scoreAdjustment??0)}"><span class="hint">Fx 10 for bonus eller -15 for fradrag.</span></label><label>Fast score<input name="overrideScore" type="number" min="0" max="100" value="${esc(r.effect?.score??'')}"><span class="hint">Kun ved typen “sætter fast score”.</span></label><label class="switch-line"><input name="block" type="checkbox" ${r.effect?.block?'checked':''}> Blokér vurderingen</label><label class="full">Forklaring / godt råd<textarea name="explanation" required placeholder="Skriv rådet i almindeligt dansk. Forklar hvorfor det betyder noget for ravjagt.">${esc(r.effect?.explanation||'')}</textarea></label><label class="full">Interne noter<textarea name="notes" placeholder="Usikkerheder, undtagelser eller hvad der bør undersøges.">${esc(r.notes||'')}</textarea></label></div>`;
 const existing=conditionsToRows(r.conditions||{});existing.forEach(addConditionRow);document.querySelector('#addCondition').onclick=()=>addConditionRow();ruleDialog.showModal();}

const conditionDefs={minWindSpeedMps:['Vindstyrke mindst','m/s'],maxWindSpeedMps:['Vindstyrke højst','m/s'],windDirection:['Vindretning','retning'],minWaveHeightM:['Bølgehøjde mindst','m'],maxWaveHeightM:['Bølgehøjde højst','m'],minWaterLevelCm:['Vandstand mindst','cm'],maxWaterLevelCm:['Vandstand højst','cm'],maxHoursSinceHighEnergy:['Højst timer siden kraftigt vejr','timer'],minBaseScore:['Grundscore mindst','point'],maxBaseScore:['Grundscore højst','point'],huntMode:['Jagtform','valg']};
function addConditionRow(row={key:'minWindSpeedMps',value:'',extra:''}){const wrap=document.querySelector('#conditionList');const div=document.createElement('div');div.className='condition-row';div.innerHTML=`<select class="cond-key">${Object.entries(conditionDefs).map(([k,v])=>`<option value="${k}" ${row.key===k?'selected':''}>${v[0]}</option>`).join('')}</select><select class="cond-op"><option value="value">Værdi</option></select><input class="cond-value" value="${esc(row.value)}" placeholder="Tal, N/NE/E… eller waders/beach"><button type="button" class="admin-button danger">×</button>`;div.querySelector('button').onclick=()=>div.remove();wrap.appendChild(div)}
function conditionsToRows(c){const rows=[];for(const k of ['minWindSpeedMps','maxWindSpeedMps','minWaveHeightM','maxWaveHeightM','minWaterLevelCm','maxWaterLevelCm','maxHoursSinceHighEnergy','minBaseScore','maxBaseScore'])if(c[k]!=null)rows.push({key:k,value:c[k]});if(c.huntModes?.length)rows.push({key:'huntMode',value:c.huntModes.join(',')});if(c.windDirectionRangesDeg?.length)rows.push({key:'windDirection',value:directionRangeToLabel(c.windDirectionRangesDeg[0])});return rows}

document.querySelector('#ruleForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const fd=new FormData(e.currentTarget);const old=state.editingId?adminRules().find(x=>x.id===state.editingId):null;const conditions={};document.querySelectorAll('.condition-row').forEach(row=>{const k=row.querySelector('.cond-key').value,v=row.querySelector('.cond-value').value.trim();if(!v)return;if(k==='huntMode')conditions.huntModes=v.split(',').map(x=>x.trim()).filter(Boolean);else if(k==='windDirection')conditions.windDirectionRangesDeg=[directionLabelToRange(v)];else conditions[k]=Number(v)});const scope=fd.get('scope');const values=String(fd.get('geoValues')||'').split(',').map(x=>x.trim()).filter(Boolean);const kind=fd.get('kind');const rule={id:old?.id||uid(),name:fd.get('name'),status:fd.get('status'),kind,knowledgeClass:fd.get('knowledgeClass'),confidence:fd.get('confidence'),priority:Number(fd.get('priority')),geography:{scope,...(scope==='zone'?{zoneIds:values}:scope==='coastType'?{coastTypes:values}:{})},source:{type:fd.get('knowledgeClass')==='expert'?'expert':'reference',title:fd.get('sourceTitle')||'Ikke angivet'},conditions,effect:{scoreAdjustment:Number(fd.get('scoreAdjustment')||0),explanation:fd.get('explanation'),...(fd.get('overrideScore')!==''?{score:Number(fd.get('overrideScore'))}:{}),...(fd.get('block')?{block:true}:{})},notes:fd.get('notes'),version:(old?.version||0)+1,updatedAt:new Date().toISOString()};const rows=adminRules();const i=rows.findIndex(x=>x.id===rule.id);if(i>=0)rows[i]=rule;else rows.push(rule);saveAdminRules(rows);addHistory(i>=0?'updated':'created',rule);ruleDialog.close();boot();});

function openTest(rule){const zones=state.zones.slice(0,100);document.querySelector('#testContent').innerHTML=`<div class="form-grid"><label>Zone<select id="testZone">${zones.map(z=>`<option value="${esc(z.properties?.id)}">${esc(z.properties?.name||z.properties?.id)}</option>`).join('')}</select></label><label>Jagtform<select id="testMode"><option value="waders">Waders</option><option value="beach">Strand</option></select></label><label>Grundscore<input id="testBase" type="number" value="50"></label><label>Vindstyrke m/s<input id="testWind" type="number" value="10"></label><label>Vindretning grader<input id="testDir" type="number" value="270"></label><label>Bølgehøjde m<input id="testWave" type="number" step="0.1" value="0.8"></label><label>Vandstand cm<input id="testWater" type="number" value="0"></label><div class="full"><button type="button" id="runTest" class="admin-button">Kør test</button></div><div id="testResult" class="full admin-card"></div></div>`;document.querySelector('#runTest').onclick=()=>{const z=state.zones.find(x=>x.properties?.id===document.querySelector('#testZone').value);const result=evaluateRules({rules:[rule],zone:{id:z?.properties?.id,coastType:z?.properties?.coastType},mode:document.querySelector('#testMode').value,baseScore:Number(document.querySelector('#testBase').value),weather:{windSpeedMps:Number(document.querySelector('#testWind').value),windDirectionDeg:Number(document.querySelector('#testDir').value),waveHeightM:Number(document.querySelector('#testWave').value),waterLevelCm:Number(document.querySelector('#testWater').value)},history:{}});document.querySelector('#testResult').innerHTML=result.matches.length?`<h3>Reglen matcher</h3><p>Resultatscore: <b>${esc(result.score)}</b> · ændring ${result.adjustment>=0?'+':''}${result.adjustment}</p><p>${esc(result.matches[0].explanation)}</p>`:'<h3>Reglen matcher ikke</h3><p>Prøv at ændre testværdierne og se, hvilke forhold der udløser den.</p>'};testDialog.showModal();document.querySelector('#runTest').click();}

function copyRule(r){const copy={...structuredClone(r),id:uid(),name:`Kopi af ${r.name}`,status:'draft',version:1,_origin:undefined};const rows=adminRules();rows.push(copy);saveAdminRules(rows);addHistory('copied',copy);boot();openRuleEditor(copy)}
function exportRules(){download(`ravradar-admin-regler-${new Date().toISOString().slice(0,10)}.json`,{schemaVersion:'1.1',exportedAt:new Date().toISOString(),rules:adminRules()})}
document.querySelector('#importRulesInput').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data.rules))throw new Error('Filen indeholder ikke en rules-liste.');const current=adminRules();for(const r of data.rules){const i=current.findIndex(x=>x.id===r.id);if(i>=0)current[i]=r;else current.push(r);addHistory('imported',r)}saveAdminRules(current);await boot();alert(`${data.rules.length} regler importeret.`)}catch(err){alert(`Import mislykkedes: ${err.message}`)}finally{e.target.value=''}});

function describeConditions(c={}){const a=[];if(c.minWindSpeedMps!=null)a.push(`vind ≥ ${c.minWindSpeedMps} m/s`);if(c.maxWindSpeedMps!=null)a.push(`vind ≤ ${c.maxWindSpeedMps} m/s`);if(c.windDirectionRangesDeg?.length)a.push('passende vindretning');if(c.minWaveHeightM!=null)a.push(`bølger ≥ ${c.minWaveHeightM} m`);if(c.maxWaveHeightM!=null)a.push(`bølger ≤ ${c.maxWaveHeightM} m`);if(c.minWaterLevelCm!=null)a.push(`vandstand ≥ ${c.minWaterLevelCm} cm`);if(c.maxWaterLevelCm!=null)a.push(`vandstand ≤ ${c.maxWaterLevelCm} cm`);if(c.maxHoursSinceHighEnergy!=null)a.push(`inden for ${c.maxHoursSinceHighEnergy} timer efter kraftigt vejr`);if(c.huntModes?.length)a.push(`jagtform: ${c.huntModes.join('/')}`);return a.join(', ')}
function describeEffect(r){if(r.kind==='annotation')return'Viser et godt råd';if(r.kind==='gate')return r.effect?.block?'Blokerer vurdering':'Gate';if(r.kind==='override')return`Sætter score til ${r.effect?.score}`;return`${Number(r.effect?.scoreAdjustment||0)>=0?'+':''}${r.effect?.scoreAdjustment||0} point`}
function describeGeo(g={}){if(!g.scope||g.scope==='national')return'Hele Danmark';if(g.scope==='zone')return`${g.zoneIds?.length||0} valgte zoner`;if(g.scope==='coastType')return`Kysttyper: ${(g.coastTypes||[]).join(', ')}`;return g.scope}
function classDa(x){return({expert:'Ravjæger-erfaring',documented:'Dokumenteret','data-derived':'Dataafledt',hypothesis:'Hypotese'})[x]||x}
function statusDa(x){return({active:'Aktiv',draft:'Kladde',inactive:'Inaktiv',retired:'Arkiveret'})[x]||x}
function directionLabelToRange(v){const m={N:[337.5,22.5],NE:[22.5,67.5],E:[67.5,112.5],SE:[112.5,157.5],S:[157.5,202.5],SW:[202.5,247.5],W:[247.5,292.5],NW:[292.5,337.5]};return m[v.toUpperCase()]||String(v).split('-').map(Number)}
function directionRangeToLabel(r){return `${r[0]}-${r[1]}`}


const saveBadge=document.createElement('div');
saveBadge.className='admin-save-status';
saveBadge.textContent=centralAdminStorageEnabled()?'Central lagring klar':'Kun lokal kladde – log ind/konfigurér Supabase';
document.body.appendChild(saveBadge);
onAdminSaveStatus(status=>{
  saveBadge.className=`admin-save-status ${status.state}`;
  saveBadge.textContent=status.state==='saving'?'Gemmer…':status.state==='saved'?`Gemt centralt ${status.at?new Date(status.at).toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit'}):''}`:`Kun lokal kladde${status.error?' · '+status.error:''}`;
});
window.addEventListener('beforeunload',e=>{if(saveBadge.classList.contains('saving')){e.preventDefault();e.returnValue='';}});


function renderHandbook(){content.innerHTML=`<article class="admin-card"><span class="eyebrow">Levende dokumentation</span><h2>RavRadar-projekthåndbogen</h2><p>Håndbogen beskriver projektets faglige model, dataflow, scoring, administration og kvalitetssikring. Eksperter kan foreslå rettelser direkte ved hvert afsnit.</p><div class="admin-actions"><a class="admin-button" href="handbook.html" target="_blank" rel="noopener">Åbn håndbogen</a><a class="admin-button secondary" href="handbook.html#ekspertreview" target="_blank" rel="noopener">Sådan gemmes rettelser</a></div><div class="status-banner ok"><strong>Vedvarende lagring</strong><p>Indsendte rettelser gemmes i Supabase-tabellerne <code>handbook_reviews</code> og <code>handbook_review_versions</code>. GitHub-deploys og nye ZIP-versioner overskriver ikke disse data.</p></div><p><strong>Lokale nødkladder på denne enhed:</strong> ${localHandbookDraftCount()}</p></article><article class="admin-card"><div class="section-head"><div><span class="eyebrow">Reviewkø</span><h2>Ekspertrettelser</h2></div><button class="admin-button secondary" id="refreshHandbookReviews">Opdatér</button></div><div id="handbookReviewList"><p>Henter rettelser…</p></div></article>`;document.querySelector('#refreshHandbookReviews').onclick=loadHandbookReviewList;loadHandbookReviewList();}
async function loadHandbookReviewList(){const box=document.querySelector('#handbookReviewList');if(!box)return;box.innerHTML='<p>Henter rettelser…</p>';try{const rows=await listHandbookReviews();box.innerHTML=rows.length?rows.map(r=>`<article class="rule-card"><div><span class="status ${esc(r.status)}">${esc(({new:'Ny',reviewing:'Under vurdering',accepted:'Accepteret',implemented:'Implementeret',rejected:'Afvist'})[r.status]||r.status)}</span><h3>${esc(r.section_title)}</h3><p><strong>Problem:</strong> ${esc(r.issue)}</p><p><strong>Forslag:</strong> ${esc(r.proposal)}</p><p><strong>Begrundelse:</strong> ${esc(r.reasoning)}</p><p class="muted">${esc(r.expert_name||'Navn ikke angivet')}${r.organization?' · '+esc(r.organization):''} · ${esc(new Date(r.created_at).toLocaleString('da-DK'))}</p></div><div class="admin-actions"><select data-review-status="${esc(r.id)}"><option value="new" ${r.status==='new'?'selected':''}>Ny</option><option value="reviewing" ${r.status==='reviewing'?'selected':''}>Under vurdering</option><option value="accepted" ${r.status==='accepted'?'selected':''}>Accepteret</option><option value="implemented" ${r.status==='implemented'?'selected':''}>Implementeret</option><option value="rejected" ${r.status==='rejected'?'selected':''}>Afvist</option></select></div></article>`).join(''):'<p>Ingen centrale ekspertrettelser endnu.</p>';box.querySelectorAll('[data-review-status]').forEach(sel=>sel.onchange=async()=>{sel.disabled=true;try{await updateHandbookReview(sel.dataset.reviewStatus,{status:sel.value});await loadHandbookReviewList();}catch(error){alert(error.message);sel.disabled=false;}});}catch(error){box.innerHTML=`<p class="status-banner warning">${esc(error.message)}. Kontrollér Supabase-migration og login.</p>`;}}
boot();
